;(function(window, document, console){
'use strict';
// page-sigil.js (S129 · audit #12)
// Tiny 28px sigil with a 44×44 touch target at the top-right of every public page.
// last-update-age (green ≤14d, amber ≤60d, red >60d). Tooltip "Last refreshed Nd ago".
// Reads /api/public-intelligence.json `pages[<path>].lastTouched`; falls back to a
// page-level `<meta name="vs:last-touched">` tag; silently noop if neither exists.
//
// ~500 bytes inline. Doesn't ship a full SVG sprite — single circle path,
// stroke-dasharray ring fills relative to (1 - age/cap) so fresh pages look
// "fuller." Links to /studio-pulse/ for the global view.
(() => {
  if (typeof window === 'undefined' || typeof document === 'undefined') return;
  if (document.documentElement.dataset.motion === 'reduced' && location.pathname === '/') {
    // Don't add visual flair on reduced-motion home — respect user preference.
  }
  if (document.querySelector('[data-vs-page-sigil]')) return;

  const FRESH_DAYS = 14;
  const STALE_DAYS = 60;

  function colorFor(days) {
    if (days <= FRESH_DAYS) return '#5be08e'; // green
    if (days <= STALE_DAYS) return '#e0b25b'; // amber
    return '#e05b5b';                          // red
  }

  function mount(days) {
    const wrap = document.createElement('a');
    wrap.href = '/studio-pulse/';
    wrap.setAttribute('data-vs-page-sigil', '');
    wrap.setAttribute('aria-label',
      `Page last refreshed ${days}d ago — see studio pulse`);
    wrap.title = `Last refreshed ${days}d ago`;
    Object.assign(wrap.style, {
      position: 'fixed', top: '2px', right: '2px', width: '44px', height: '44px',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      zIndex: '40', opacity: '0.55', textDecoration: 'none',
      transition: 'opacity 180ms ease', pointerEvents: 'auto'
    });
    wrap.addEventListener('mouseenter', () => { wrap.style.opacity = '0.95'; });
    wrap.addEventListener('mouseleave', () => { wrap.style.opacity = '0.55'; });

    const color = colorFor(days);
    const fillRatio = Math.max(0.12, 1 - Math.min(days, 90) / 90);
    const circumference = 2 * Math.PI * 11; // r=11
    const dash = circumference * fillRatio;
    // S174 TT burndown: SVG via createElementNS instead of innerHTML.
    const SVG_NS = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(SVG_NS, 'svg');
    svg.setAttribute('viewBox', '0 0 28 28');
    svg.setAttribute('width', '28');
    svg.setAttribute('height', '28');
    svg.setAttribute('aria-hidden', 'true');
    const circle = (attrs) => {
      const c = document.createElementNS(SVG_NS, 'circle');
      c.setAttribute('cx', '14');
      c.setAttribute('cy', '14');
      for (const [k, v] of Object.entries(attrs)) c.setAttribute(k, v);
      return c;
    };
    svg.appendChild(circle({ r: '11', fill: 'none', stroke: `${color}33`, 'stroke-width': '2' }));
    svg.appendChild(circle({
      r: '11', fill: 'none', stroke: color, 'stroke-width': '2',
      'stroke-dasharray': `${dash.toFixed(1)} ${circumference.toFixed(1)}`,
      'stroke-linecap': 'round', transform: 'rotate(-90 14 14)',
    }));
    svg.appendChild(circle({ r: '2.4', fill: color }));
    wrap.appendChild(svg);
    document.body.appendChild(wrap);
  }

  function fromMeta() {
    const m = document.querySelector('meta[name="vs:last-touched"]');
    if (!m) return null;
    const t = Date.parse(m.getAttribute('content'));
    if (Number.isNaN(t)) return null;
    return Math.max(0, Math.round((Date.now() - t) / 86400000));
  }

  async function fromAPI() {
    try {
      const data = window.VSPublicSignals
        ? await window.VSPublicSignals.get('/api/public-intelligence.json')
        : await fetch('/api/public-intelligence.json', { cache: 'no-store' }).then(r => r.ok ? r.json() : null);
      if (!data) return null;
      const ts = data?.generatedAt || data?.lastUpdated || data?.updated;
      if (!ts) return null;
      const t = Date.parse(ts);
      if (Number.isNaN(t)) return null;
      return Math.max(0, Math.round((Date.now() - t) / 86400000));
    } catch { return null; }
  }

  // Skip portals/admin and pages that opt-out.
  const skip = /^\/(vault-member|investor-portal|studio-hub|admin)/.test(location.pathname);
  if (skip || document.body.hasAttribute('data-no-sigil')) return;

  if ('requestIdleCallback' in window) {
    requestIdleCallback(async () => {
      const days = fromMeta() ?? await fromAPI();
      if (days === null) return;
      mount(days);
    }, { timeout: 2000 });
  } else {
    setTimeout(async () => {
      const days = fromMeta() ?? await fromAPI();
      if (days === null) return;
      mount(days);
    }, 800);
  }
})();

})(window, document, console);

/* ── assets/vault-atlas.js ──────────────────────────────────────────── */
;(function(window, document, console){
'use strict';
// vault-atlas.js (S129 · audit #9)
// Vault Atlas — a 5-dot live status strip that appears at the top of the
// Resources dropdown. Each dot reflects a real surface:
//   • homepage    — synthetic /api/ci-status.json `homepage.ok`
//   • pulse       — public-intelligence freshness (≤7d green, ≤30d amber)
//   • hub         — founder-presence.json `online` flag
//   • ignis       — ignis_alerts surface (degraded → amber, down → red)
//   • checkout    — Stripe price endpoint reachability cached server-side
//
// Sources are best-effort — anything 404/timeout renders neutral gray.
// Refreshes every 90 s while the dropdown is open. ~2 KB on the wire.
(() => {
  if (typeof window === 'undefined' || typeof document === 'undefined') return;

  const SURFACES = [
    { key: 'homepage', label: 'Homepage' },
    { key: 'pulse',    label: 'Studio Pulse' },
    { key: 'hub',      label: 'Hub' },
    { key: 'ignis',    label: 'IGNIS' },
    { key: 'checkout', label: 'Checkout' },
  ];
  const COLORS = { up: '#5be08e', degraded: '#e0b25b', down: '#e05b5b', unknown: '#888' };
  let refreshTimer = null;

  function findResourcesDropdown() {
    return document.querySelector('[data-resources-dropdown]') ||
           Array.from(document.querySelectorAll('.nav-dropdown')).find((el) => {
             const trigger = el.querySelector('button, a');
             return trigger && /resources/i.test(trigger.textContent || '');
           });
  }

  async function snapshot() {
    const out = {};
    for (const s of SURFACES) out[s.key] = 'unknown';
    const safe = async (fn) => { try { return await fn(); } catch { return null; } };

    const [ci, pi, fp] = await Promise.all([
      safe(() => fetch('/api/ci-status.json', { cache: 'no-store' }).then(r => r.ok ? r.json() : null)),
      safe(() => window.VSPublicSignals ? window.VSPublicSignals.get('/api/public-intelligence.json') : fetch('/api/public-intelligence.json', { cache: 'no-store' }).then(r => r.ok ? r.json() : null)),
      safe(() => window.VSPublicSignals ? window.VSPublicSignals.get('/api/founder-presence.json', { ttlMs: 90000 }) : fetch('/api/founder-presence.json', { cache: 'no-store' }).then(r => r.ok ? r.json() : null)),
    ]);

    if (ci) out.homepage = ci.ok !== false ? 'up' : 'down';
    if (pi) {
      const ts = pi.generatedAt || pi.lastUpdated;
      if (ts) {
        const days = (Date.now() - Date.parse(ts)) / 86400000;
        out.pulse = days <= 7 ? 'up' : days <= 30 ? 'degraded' : 'down';
      }
    }
    if (fp) out.hub = fp.online ? 'up' : 'degraded';

    // IGNIS — heuristic: if public-intelligence has ignis block, treat as up
    if (pi && (pi.ignisDailyMeter || pi.ignis)) out.ignis = 'up';

    // Checkout — assume up if no signal (it's hard to probe Stripe from client without leaking key)
    out.checkout = ci && ci.checkout ? ci.checkout : 'unknown';
    return out;
  }

  function render(strip, status) {
    const parts = SURFACES.map((s) => {
      const v = status[s.key] || 'unknown';
      const color = COLORS[v] || COLORS.unknown;
      return `<span title="${s.label}: ${v}"
        style="display:inline-block;width:8px;height:8px;border-radius:50%;
        background:${color};margin-right:6px;vertical-align:middle;
        box-shadow:0 0 6px ${color}66"></span>`;
    });
    strip.innerHTML = `<div style="padding:8px 12px;font:11px/1.4 system-ui;opacity:.78;
      border-bottom:1px solid rgba(255,255,255,.08);margin-bottom:4px">
      <span style="text-transform:uppercase;letter-spacing:.08em;font-weight:600;
        margin-right:8px;opacity:.6">Live</span>${parts.join('')}
      <a href="/status/" data-no-prerender
         style="float:right;color:inherit;opacity:.6;text-decoration:none">details →</a>
    </div>`;
  }

  async function mount() {
    const dropdown = findResourcesDropdown();
    if (!dropdown) return;
    const panel = dropdown.querySelector('.nav-dropdown-menu, [role="menu"], ul') || dropdown;
    if (panel.querySelector('[data-vs-atlas]')) return;

    const strip = document.createElement('div');
    strip.setAttribute('data-vs-atlas', '');
    panel.insertBefore(strip, panel.firstChild);
    render(strip, Object.fromEntries(SURFACES.map(s => [s.key, 'unknown'])));

    const status = await snapshot();
    render(strip, status);

    if (refreshTimer) clearInterval(refreshTimer);
    refreshTimer = setInterval(async () => {
      if (!document.body.contains(strip)) { clearInterval(refreshTimer); return; }
      render(strip, await snapshot());
    }, 90000);
  }

  if ('requestIdleCallback' in window) {
    requestIdleCallback(mount, { timeout: 2500 });
  } else {
    setTimeout(mount, 1200);
  }
})();

})(window, document, console);

/* ── assets/founder-presence-handle.js ──────────────────────────────────────────── */
;(function(window, document, console){
'use strict';
/* founder-presence-handle.js — S159 audit #13.
 *
 * When the founder is active in studio-hub (signal from /api/founder-presence.json),
 * set body[data-founder-active]. Sitewide CSS gives the wordmark a 1px gold
 * underline. Subtle parasocial cue: "the studio is a person, and they're here."
 *
 * Listens to the same BroadcastChannel('vault-presence') that favicon-pulse.js
 * uses — zero extra polling. Falls back to a single fetch when broadcast hasn't
 * arrived yet (page loaded after favicon-pulse already drained the channel).
 *
 * No DOM mutation beyond a body attribute. CSS does the rest. CLS-safe.
 */
(function () {
  'use strict';
  if (typeof document === 'undefined' || typeof window === 'undefined') return;

  const BC_NAME = 'vault-presence';
  const PRESENCE_URL = '/api/founder-presence.json';
  const ATTR = 'data-founder-active';

  function apply(active) {
    const wasActive = document.body.hasAttribute(ATTR);
    if (active && !wasActive) document.body.setAttribute(ATTR, '');
    else if (!active && wasActive) document.body.removeAttribute(ATTR);
  }

  // Listen for sibling-tab broadcasts from favicon-pulse.js leader.
  let bc = null;
  try { bc = ('BroadcastChannel' in window) ? new BroadcastChannel(BC_NAME) : null; } catch (_) { bc = null; }
  if (bc) {
    bc.onmessage = (e) => {
      const d = e && e.data;
      if (!d || typeof d.active !== 'boolean') return;
      apply(d.active);
    };
  }

  // Cold-start fallback: one fetch on idle to get initial state before the
  // first broadcast tick. Cheap; same shape favicon-pulse reads.
  function coldFetch() {
    (window.VSPublicSignals
      ? window.VSPublicSignals.get(PRESENCE_URL, { ttlMs: 90000 })
      : fetch(PRESENCE_URL, { cache: 'no-store' }).then((r) => r.ok ? r.json() : null))
      .then((j) => {
        const active = !!(j && (j.active === true || j.live === true || j.activeUntil));
        apply(active);
      })
      .catch(() => { /* fail-silent */ });
  }
  if ('requestIdleCallback' in window) {
    requestIdleCallback(coldFetch, { timeout: 3000 });
  } else {
    setTimeout(coldFetch, 1500);
  }
})();

})(window, document, console);
